/**
 * pipeline-master-persona-copy.ts
 *
 * D15 persona overlay side-car for pipeline-master.ts.
 *
 * WHY A SIDE-CAR:
 *   pipeline-master.ts is generated by the W2 codemod from
 *   crispro_master_pipeline.json. Adding personaCopy fields inline would
 *   either couple the generator to persona logic (larger scope) or be
 *   blown away on the next regeneration. Instead this file carries the
 *   overlay in a parallel structure keyed by `program_id`.
 *
 * WHAT IT COVERS (D15 first pass):
 *   Program-header copy only — program_name, headline, indication_focus,
 *   ip_value, admissibility. Persona-varied strings for `patient` and
 *   `pharma`; the English root in pipeline-master.ts is the oncologist
 *   baseline by design.
 *
 * WHAT IT DOES NOT COVER (deferred):
 *   Program-level key_findings, transfer_lessons, and trial-level
 *   primary_result / outcome / failure_mode. These carry dense cited
 *   statistical evidence (HR / OS / PFS / PMIDs / p-values) — adapting
 *   them to plain-English patient framing risks losing the numeric
 *   precision the audit trail depends on. That pass gets its own chunk
 *   if the reviewer signs off on the interpretation risk.
 *
 * READ SITES:
 *   import { getPipelinePersonaHeader } from '@/data/pipeline-master-persona-copy';
 *   const header = getPipelinePersonaHeader(program.program_id, persona);
 *   // Returns program-header fields with persona-appropriate voice, or
 *   // falls back to the English root fields from the passed-in program.
 */

import type { Persona } from '@/context/PersonaContext';
import type { PipelineProgram } from './pipeline-master';

export interface PipelineProgramCopyFields {
  program_name: string;
  headline: string;
  indication_focus: string;
  ip_value: string;
  admissibility: string;
}

export type PipelineProgramPersonaOverlay = Partial<
  Record<Persona, Partial<PipelineProgramCopyFields>>
>;

