/**
 * Return persona-adjusted program-header copy for a pipeline program.
 * Falls back to the English root fields on the passed-in program.
 */
export function getPipelinePersonaHeader(
  program: Pick<PipelineProgram, 'program_id' | 'program_name' | 'headline' | 'indication_focus' | 'ip_value' | 'admissibility'>,
  persona: Persona,
): PipelineProgramCopyFields {
  const overlay = PIPELINE_PROGRAM_PERSONA_COPY[program.program_id]?.[persona];
  return {
    program_name: overlay?.program_name ?? program.program_name,
    headline: overlay?.headline ?? program.headline,
    indication_focus: overlay?.indication_focus ?? program.indication_focus,
    ip_value: overlay?.ip_value ?? program.ip_value,
    admissibility: overlay?.admissibility ?? program.admissibility,
  };
}
